import React from 'react';

import 'leaflet/dist/leaflet.css';

import { Link } from 'react-router-dom';

import { getHikingDataAsync } from '@apps/Hiking/@services/hiking.service';
import { editHikingGpx, getHikingGpxTrackById } from '@apps/Hiking/@services/hikingResults.service';
import { IHikingData, IHikingGpxWithWorkout } from '@apps/Hiking/@types/hiking.types';
import ScheduleItem from '@apps/Hiking/schedule/components/ScheduleItem';
import { getOneWorkout } from '@apps/Workouts/@services/workouts.service';
import { IWorkout, IWorkoutFull } from '@apps/Workouts/@types/workouts.types';
import WorkoutMarkupEdit from '@apps/Workouts/components/WorkoutMarkupEdit';
import WorkoutStat from '@apps/Workouts/Workout/WorkoutStat';
import WorkoutListItem from '@apps/Workouts/WorkoutListItem';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import { editHikingTrackAsync } from './HikingTrackEditModal';

interface IHikingTrackOneProps {
  id_hiking: number;
  id_hiking_track: number;
}

const HikingTrackOne: React.FC<IHikingTrackOneProps> = ({ id_hiking, id_hiking_track }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [track, setTrack] = React.useState<IHikingGpxWithWorkout>();
  const [workout, setWorkout] = React.useState<IWorkoutFull>();
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();

  React.useEffect(() => {
    const fetchData = async () => {
      try {
        setIsLoading(true);
        const hd = await getHikingDataAsync(id_hiking);
        setHikingData(hd);

        const td = await getHikingGpxTrackById(id_hiking_track);
        setTrack(td);

        const wd = await getOneWorkout(td.workout.id);
        setWorkout(wd);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [id_hiking, id_hiking_track]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!hikingData) {
    return <PohAlert variant={AlertVariant.Danger}>Has no hikingData</PohAlert>;
  }

  if (!track) {
    return <PohAlert variant={AlertVariant.Danger}>Has no hiking track</PohAlert>;
  }

  if (!workout) {
    return <PohAlert variant={AlertVariant.Danger}>Has no workout</PohAlert>;
  }

  return (
    <>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/tracks`, text: 'GPS Треки' },
          {
            href: `/hiking/${id_hiking}/tracks/${id_hiking_track}`,
            text: track.name,
            active: true,
          },
        ]}
      />
      <PohContainer>
        <PageHeader title={track.name}>
          <PohButton
            onClick={async () => {
              const a = await editHikingTrackAsync(id_hiking, track);

              editHikingGpx({
                id_hiking_track,
                name: a.name,
                id_hiking_schedule: a.id_hiking_schedule,
              }).then(() => {
                setTrack((cur) =>
                  cur
                    ? {
                        ...cur,
                        name: a.name,
                        id_hiking_schedule: a.id_hiking_schedule,
                        schedule: a.schedule,
                      }
                    : cur,
                );
              });
            }}
            size={ButtonSize.Small}
          >
            Изменить
          </PohButton>
        </PageHeader>
        <PohRow>
          <PohCol sm={12}>
            Трек загружен из тренировки
            <Link to={`/workouts/${workout.id}`}>
              <WorkoutListItem data={workout as unknown as IWorkout} />
            </Link>
          </PohCol>
        </PohRow>

        <PohRow>
          <PohCol sm={12} className="mt-2">
            <WorkoutStat data={workout} />
          </PohCol>
        </PohRow>

        <PohRow>
          <PohCol sm={12} className="mt-3">
            <h5 className="mt-3 mb-0">Разметка трека</h5>
            <WorkoutMarkupEdit workout={workout} />
          </PohCol>
        </PohRow>
        {track.schedule && (
          <PohRow className="mt-2">
            <PohCol sm={2} className="pt-2">
              Связь с планом похода
            </PohCol>
            <PohCol sm={10}>
              <ScheduleItem
                id_hiking={id_hiking}
                scheduleItem={track.schedule}
                className="border-top-0"
              />
            </PohCol>
          </PohRow>
        )}
      </PohContainer>
    </>
  );
};

export default HikingTrackOne;
